<template>
  <div class="kiosk-showcase" :class="{ 'hq-brand': product === 'hq' }">
    <div class="showcase-caption"><span>{{ brandName }} presentation · Fictional practice and visit</span><button type="button" @click="reset">Reset example ↺</button></div>
