        <div class="kiosk-content">
          <p class="screen-eyebrow">CLIENT CHECK-IN <span>9:54 AM · MON, OCT 5</span></p>
          <template v-if="step === 'welcome'">
            <h3 ref="stepHeading" tabindex="-1">Make yourself<br><em>at home.</em></h3><p>Choose your provider. We’ll let them know you’re here.</p>
            <div class="kiosk-provider"><KioskProviderCard :provider="provider" @select="showStep('confirm')" @photo="showStep('profile')" @profile="showStep('profile')" /></div>
            <p class="private-hint">No client names appear on the office directory.</p>
          </template>
          <template v-else-if="step === 'profile'">
            <h3 ref="stepHeading" tabindex="-1">Meet Jordan.</h3><div class="selected-provider"><img src="/auricwell/examples/jordan-reed.jpg" alt="Fictional provider Jordan Reed" /><div><strong>Jordan Reed, LCSW</strong><span>Individual therapy · Adults</span></div></div>
            <p>I help adults make space for change, build practical coping skills, and feel more connected in everyday life.</p><p class="private-hint">Fictional biography and generated portrait.</p><button class="primary-action" @click="showStep('confirm')">10:00 AM · Check in →</button><button class="plain-action" @click="showStep('welcome')">Back to providers</button>
          </template>
          <template v-else-if="step === 'confirm'">
            <h3 ref="stepHeading" tabindex="-1">Ready to check in?</h3><p>We’ll let your provider know you’ve arrived.</p>
            <div class="selected-provider"><img src="/auricwell/examples/jordan-reed.jpg" alt="" /><div><strong>Jordan Reed, LCSW</strong><span>10:00 AM · Office 204</span></div></div>
