          <template v-else>
            <span class="arrival-check" aria-hidden="true">✓</span><h3 ref="stepHeading" tabindex="-1">You’re checked in.</h3><p>Make yourself comfortable in the lobby. Jordan will come get you.</p><div class="visit-receipt"><strong>10:00 AM</strong><span>Jordan Reed · Office 204</span><small>Therapy / counseling</small></div><p class="demo-local" role="status">Sample arrival shown. No appointment was changed and no notification was sent.</p><button class="primary-action" @click="showStep('welcome')">Return to welcome →</button>
