<script setup>
import {computed, ref, nextTick} from 'vue';
import KioskProviderCard from '../../components/kiosk/KioskProviderCard.vue';
const props=defineProps({product:{type:String,default:'auricwell'}});
const brandName=computed(()=>props.product === 'hq' ? 'Plot Twist HQ' : 'AuricWell');
const brandLogo=computed(()=>props.product === 'hq' ? '/assets/ptco/logo-flat.webp' : '/auricwell/logo.png');
const step=ref('welcome'), stepHeading=ref(null), respondent=ref(''), arrived=ref(false), acknowledged=ref(false), channel=ref('app');
// This shared card resolves uploaded photos against the backend. Absolute,
// same-origin public asset URLs keep this example entirely on the website.
const asset=path=>new URL(path,window.location.origin).href;
const provider=computed(()=>({id:902,firstName:'Jordan',lastName:'Reed',credential:'LCSW',profilePhotoPath:asset('/auricwell/examples/jordan-reed.jpg'),agencyLogoPath:asset(brandLogo.value),agencyName:'Meadowbrook Therapy',currentRoomNumber:'204',currentSlot:{startAt:'2026-10-05 10:00:00',checkedIn:false}}));
const respondents=[{id:'adult',label:'I’m answering for myself (18 or older)'},{id:'youth',label:'I’m answering for myself (under 18)'},{id:'caregiver',label:'I’m answering for my dependent'}];
const channels=[{id:'app',label:'In-app alert'},{id:'email',label:'Email'},{id:'sms',label:'Provider SMS'}];
const metrics=[{label:'Connection',current:'8.2',previous:'7.5',average:'7.6'},{label:'Progress',current:'7.0',previous:'6.0',average:'6.4'}];
async function showStep(value){step.value=value;await nextTick();stepHeading.value?.focus();}
function checkIn(){arrived.value=true;acknowledged.value=false;channel.value='app';showStep('done');}
function reset(){respondent.value='';arrived.value=false;acknowledged.value=false;channel.value='app';showStep('welcome');}
</script>
